$path = 'src/explore/hieu-viet-nam/data/cau-hoi.json'
$questions = Get-Content -Raw -Encoding utf8 $path | ConvertFrom-Json
$hints = @'
{
  "bac-01":"Nhìn vào màu sợi bánh và phần cua đồng trong nước dùng.","bac-02":"Dấu hiệu quyết định là dòng sông ở đường biên với Trung Quốc.","bac-03":"Hãy nghĩ đến lối hát giao duyên có hai nhóm nam nữ đối đáp.","bac-04":"Gợi nhớ hạt nếp còn non và mùi lá sen của mùa thu.","bac-05":"Hãy chọn quần thể có hành trình đi đò luồn qua các hang nước.","bac-06":"Mùng 10 tháng Ba âm lịch là mốc lễ rất dễ nhận ra.","bac-07":"Tân Cương là manh mối về thức uống được hãm từ búp non.","bac-08":"Ở miền Tây, quả này còn có một tên bắt đầu bằng chữ “th”.",
  "trung-01":"Mùi sả và mắm ruốc phân biệt món này với nhiều loại bún khác.","trung-02":"Nhớ lại tên con sông từng làm ranh giới tạm thời sau năm 1954.","trung-03":"Đọc lần lượt ba từ theo nghĩa “đâu – kia – sao”.","trung-04":"Đặc điểm then chốt là tô sợi chỉ chan rất ít nước dùng.","trung-05":"Tên nơi này ghép từ một vùng cửa sông và một đầm nước lớn.","trung-06":"Tên điệu hò có nhịp điệu gợi động tác chèo thuyền chậm rãi.","trung-07":"Hãy chọn cách gọi kính trọng, không phải cách phân biệt quan hệ họ hàng.","trung-08":"Từ này chỉ điều đang ở gần người nói.",
  "taynguyen-01":"Cách chế biến nằm ở chiếc ống tre hoặc nứa dùng để nấu.","taynguyen-02":"Tên núi được ghép từ tên hai nhân vật trong một chuyện tình.","taynguyen-03":"Đây là bộ nhạc khí kim loại được diễn tấu thành dàn.","taynguyen-04":"Chọn từ địa phương dùng cho đơn vị cư trú của người Ê Đê.","taynguyen-05":"Mái rất cao cho thấy đây là không gian chung của cả làng.","taynguyen-06":"Nghi lễ được nhận ra qua vật hiến sinh lớn và dịp mừng mùa.","taynguyen-07":"Hạt nông sản này thường được rang, xay rồi pha thành đồ uống.","taynguyen-08":"Kiểu nhà này đủ dài để nhiều thế hệ theo mẫu hệ cùng sinh sống.",
  "nam-01":"Tìm món sợi gạo rất quen ở các quán ăn Nam Bộ.","nam-02":"Đây là mốc cực Nam có cùng tên với tỉnh được nêu trong câu.","nam-03":"Đọc nhanh tên năm thứ quả theo âm gần với một lời chúc.","nam-04":"Hình dáng gói dài như một đòn và lớp lá bọc là manh mối.","nam-05":"Đây là tiếng gọi gia súc quen thuộc trong lời nói miền Nam.","nam-06":"Hàng hóa được treo lên cây bẹo, nên chợ không họp trên đất liền.","nam-07":"Hãy hình dung chiếc phin nhỏ, sữa đặc và ly đá.","nam-08":"Từ cần chọn là cách gọi bông hoa trong lời nói miền Nam.",
  "bien-01":"Loài cá nhỏ, thân trong là nguyên liệu nhận diện của món gỏi.","bien-02":"Đảo được hỏi thuộc cùng quần đảo với tên gọi quen ở Hải Phòng.","bien-03":"Trong tín ngưỡng ngư dân, con vật này được tôn như vị thần phù hộ.","bien-04":"Chú ý huyện đảo nổi tiếng nhờ tỏi và dấu tích núi lửa.","bien-05":"Đây là tên gọi phương tiện thủy nhỏ trên sông rạch, không phải dụng cụ chứa nước.","bien-06":"Tên lễ nói thẳng mong muốn về một chuyến ra khơi an lành.","bien-07":"Loài cá rất nhỏ được ủ muối là chìa khóa để nhận ra đặc sản.","bien-08":"Sản vật được tạo bởi loài chim kết tổ từ nước bọt.",
  "bac-09":"Bánh được làm chín bằng hơi nước rồi cuốn nhân mộc nhĩ.","bac-10":"Nguyên liệu chính là một loài thân mềm biển được giã làm chả.","bac-11":"Lớp đậu vàng tán mịn và hành phi là dấu hiệu đặc trưng.","bac-12":"Tìm hồ nằm trong vườn quốc gia cùng tên, có nhiều đảo đá.","bac-13":"Đỉnh cao nhất cả nước thuộc dãy Hoàng Liên Sơn.","bac-14":"Vị anh hùng trong manh mối gắn với ngựa sắt và làng Phù Đổng.","bac-15":"Tên loại hình này trùng với tên mùa xuân, gắn vùng đất Tổ.","bac-16":"Hãy nhớ cách gọi mẹ trong câu hỏi dân gian “ai ơi bưng bát cơm đầy”.","bac-17":"Miền Bắc dùng từ khác miền Nam cho cây cho hạt làm bắp rang.","bac-18":"Sân khấu của loại hình này là mặt ao, không phải sàn diễn khô.","bac-19":"Đây là thức quà chua ngọt thường bán trong lọ nhỏ ở Hà Nội.","bac-20":"Tên dòng tranh trùng với tên làng ở Bắc Ninh, in từ ván khắc.",
  "trung-09":"Sợi dai, thịt xá xíu và rất ít nước là bộ ba dấu hiệu.","trung-10":"Bánh được đổ từng chiếc trong khuôn đất nung nhỏ.","trung-11":"Tên vườn quốc gia gắn với hệ hang động chứa Sơn Đoòng.","trung-12":"Đừng nhầm mũi đất này với Mũi Cà Mau; hãy chọn tỉnh ở duyên hải Nam Trung Bộ cũ.","trung-13":"Tên sự kiện ghép tên cố đô với một từ chỉ ngày hội quy mô lớn.","trung-14":"Sự kiện diễn ra trên sông Kiến Giang vào dịp Quốc khánh.","trung-15":"Hãy tìm loại hình kết hợp rút thẻ bài với hô hát trong chòi.","trung-16":"Đây là từ chỉ trạng thái hoặc cách thức, như “như vậy”.","trung-17":"Từ này dùng để trỏ một nơi ở xa người nói.","trung-18":"Không chọn vai vế nam; đây là cách gọi nữ giới thân mật.","trung-19":"Điểm riêng là bài thơ được lồng giữa hai lớp lá.","trung-20":"Nhà có khung gỗ, nhiều gian và mái thấp là dấu hiệu chính.",
  "taynguyen-09":"Hãy nghĩ đến loại lá rừng có vị hơi đắng, thường nấu cùng thực phẩm khác.","taynguyen-10":"Cách dọn hai tô riêng biệt là manh mối khác thường nhất.","taynguyen-11":"Màu đỏ của món này đến từ hạt điều, không phải cà chua.","taynguyen-12":"Biệt danh ví với vịnh nổi tiếng ở miền Bắc sẽ dẫn đến đáp án.","taynguyen-13":"Tên gọi này nghe như một vùng nước mênh mông dù nằm trên cao nguyên.","taynguyen-14":"Nghi lễ diễn ra khi mùa màng đã thu hoạch, nhằm tạ ơn.","taynguyen-15":"Sự kiện có tên ghép giữa cây trồng chủ lực và đô thị cao nguyên.","taynguyen-16":"Từ trong địa danh Pleiku chỉ cộng đồng cư trú, không chỉ cảnh quan.","taynguyen-17":"Yếu tố này xuất hiện trước tên nhiều dòng nước ở Tây Nguyên.","taynguyen-18":"Chú ý loại vải thủ công nổi bật bởi hoa văn dệt sợi màu.","taynguyen-19":"Đồ uống này được chuyền qua những ống dài cắm vào chum.","taynguyen-20":"Nơi này được biết đến nhờ mối quan hệ lâu đời giữa cư dân và voi.",
  "nam-09":"Bánh được đổ thật mỏng, rồi gập nhân tôm thịt bên trong.","nam-10":"Nước dùng của món này lấy hương vị đậm từ mắm và sả.","nam-11":"Khu bảo tồn đất ngập nước này nổi tiếng với nhiều chim nước.","nam-12":"Tên ngọn núi trùng với màu sẫm, nằm ở Tây Ninh.","nam-13":"Chọn quần đảo có vườn quốc gia cùng tên ở vùng biển phía nam.","nam-14":"Tên cuộc đua gắn với loại thuyền dài của cộng đồng Khmer.","nam-15":"Sự kiện tôn vinh loại cây cho trái, nước và nhiều sản phẩm gia dụng.","nam-16":"Đây là tiếng gọi cha đậm sắc thái Nam Bộ.","nam-17":"Từ được hỏi là cách nói thông dụng chỉ hoạt động lao động.","nam-18":"Nhìn vào những lò có ống khói ven sông để xác định nghề thủ công.","nam-19":"Hình dung bộ đồ thân dài, cổ tròn, phối với quần đen của người Nam Bộ.","nam-20":"Dàn nhạc có guitar phím lõm là dấu hiệu rất riêng của loại hình này.",
  "bien-09":"Tên món gợi hành động thực khách làm với phần nước chấm.","bien-10":"Bánh nhỏ được áp trong khuôn, vỏ giòn và thường có hải sản.","bien-11":"Đây là đảo giữ vai trò trung tâm hành chính của cả quần đảo.","bien-12":"Di sản này nổi bật bởi hàng nghìn đảo đá vôi nhô lên từ mặt biển.","bien-13":"Nghi lễ tưởng niệm những người từng làm nhiệm vụ ở Hoàng Sa.","bien-14":"Tên sự kiện ghép tên bờ biển với thành phố du lịch nổi tiếng.","bien-15":"Đây là một dạng ngư cụ dựng cố định sát bờ, không phải đồ đựng cá.","bien-16":"Hãy chọn từ chỉ vùng nước kín gió, nơi thuyền có thể trú.","bien-17":"Đặc điểm của dạng mặt nước này là ven biển và được che chắn tương đối.","bien-18":"Nước biển được phơi nắng trong các ô ruộng để kết tinh gia vị.","bien-19":"Sản phẩm có hương vị từ quá trình ủ cá biển với muối.","bien-20":"Phương tiện này tròn, bằng tre đan và thường được kéo lên bãi cát."
