'@ | ConvertFrom-Json

foreach ($question in $questions) { $question.goiY = $hints.($question.id) }

$updates = @{
  'trung-04'=@{tinh='da-nang';cauHoi='Món sợi vàng ăn với ít nước dùng, rau sống và đậu phộng, nổi tiếng ở Quảng Nam cũ, nay thuộc Đà Nẵng, là gì?';giaiThich='Mì Quảng thường chỉ chan ít nước dùng. Điều bất ngờ: bánh tráng nướng bẻ vụn là phần ăn kèm đặc trưng.'}
  'trung-06'=@{tinh='quang-tri';giaiThich='Hò khoan Lệ Thủy gắn với lao động và lễ hội ở Quảng Bình cũ, nay thuộc Quảng Trị. Điều bất ngờ: “khoan” gợi nhịp chèo thuyền khoan thai.'}
  'trung-09'=@{tinh='da-nang';cauHoi='Món mì Hội An ở Quảng Nam cũ, nay thuộc Đà Nẵng, dùng sợi dai, nước xá xíu và rau sống, thường được gọi là gì?'}
  'trung-11'=@{tinh='quang-tri';giaiThich='Phong Nha – Kẻ Bàng ở Quảng Bình cũ, nay thuộc Quảng Trị, nổi tiếng với địa hình karst và nhiều hang động. Điều bất ngờ: Sơn Đoòng nằm trong vùng di sản này.'}
  'trung-14'=@{tinh='quang-tri';giaiThich='Hội đua thuyền Lệ Thủy diễn ra trên sông Kiến Giang ở Quảng Bình cũ, nay thuộc Quảng Trị. Điều bất ngờ: đây là hoạt động văn hóa cộng đồng quen thuộc dịp Quốc khánh.'}
  'trung-15'=@{tinh='da-nang'}
  'trung-18'=@{tinh='da-nang'}
  'bien-03'=@{tinh='tp-ho-chi-minh';giaiThich='Ngư dân kính gọi cá voi là Cá Ông và cầu phù hộ khi ra khơi. Điều bất ngờ: lễ thường có nghi thức rước sắc thần trên biển.'}
  'bien-05'=@{tinh='vinh-long'}
  'bien-07'=@{tinh='an-giang'}
  'nam-10'=@{cauHoi='Món bún của vùng Sóc Trăng cũ, nay thuộc Cần Thơ, có nước dùng từ mắm và thường ăn kèm cá, tôm, gọi là gì?';giaiThich='Bún nước lèo là món bún đặc trưng của Sóc Trăng cũ, nay thuộc Cần Thơ. Điều bất ngờ: nước dùng thường kết hợp hương vị từ mắm và sả.'}
  'nam-13'=@{tinh='tp-ho-chi-minh';giaiThich='Côn Đảo là quần đảo nay thuộc TP. Hồ Chí Minh. Điều bất ngờ: hệ sinh thái biển và rừng ở đây được bảo vệ trong vườn quốc gia.'}
  'nam-15'=@{cauHoi='Sự kiện văn hóa tôn vinh cây dừa và sản phẩm từ dừa ở Bến Tre cũ, nay thuộc Vĩnh Long, được gọi là gì?';giaiThich='Lễ hội Dừa giới thiệu giá trị của cây dừa và sản phẩm địa phương ở Bến Tre cũ, nay thuộc Vĩnh Long. Điều bất ngờ: vùng này thường được gọi bằng tên thân thuộc gắn với loại cây này.'}
  'bien-09'=@{tinh='an-giang'}
  'bien-11'=@{tinh='tp-ho-chi-minh';giaiThich='Côn Sơn là đảo lớn nhất trong quần đảo Côn Đảo, nay thuộc TP. Hồ Chí Minh. Điều bất ngờ: phần lớn diện tích tự nhiên của quần đảo được bảo vệ trong vườn quốc gia.'}
  'bien-15'=@{tinh='da-nang'}
  'bien-20'=@{tinh='da-nang'}
  'nam-17'=@{cauHoi='Trong lời nói Nam Bộ, “đi mần” thường có nghĩa là đi làm gì?';luaChon=@('Đi làm','Đi chơi','Đi chợ','Đi học');dapAn=0;giaiThich='“Mần” là cách nói Nam Bộ tương ứng với “làm”. Điều bất ngờ: từ này thường xuất hiện trong lời nói thân mật hằng ngày.'}
}
foreach ($question in $questions) { if ($updates.ContainsKey($question.id)) { foreach ($property in $updates[$question.id].Keys) { $question.$property = $updates[$question.id][$property] } } }

($questions | Where-Object id -eq 'taynguyen-04').cauHoi = 'Trong cách gọi của người Ê Đê ở Tây Nguyên, tên đơn vị cư trú truyền thống tương đương với “làng” là gì?'
($questions | Where-Object id -eq 'taynguyen-20').chuDe = 'đời sống thường ngày'
($questions | Where-Object id -eq 'nam-19').chuDe = 'đời sống thường ngày'
$sources = @{
 'taynguyen-09'='https://govietnam.travel/en/food/canh-la-bep-la-mi/'; 'taynguyen-10'='https://mst.gov.vn/loai-pho-khac-nguoi-goi-mot-duoc-hai-o-gia-lai-sao-nguoi-la-ham-an-ton-len-hang-dac-san-197159856.htm'; 'taynguyen-15'='https://baodaklak.vn/file/fb9e3a03798789de0179a1704dea238e/upload/xdata/202503/202503132250357798.pdf'; 'nam-14'='https://soctrangtourism.vn/le-hoi-dua-ghe-ngo-soc-trang-net-van-hoa-dac-sac-gan-ket-cong-dong/'; 'bien-12'='https://whc.unesco.org/en/list/672/'; 'bien-13'='https://quangngai.gov.vn/du-lich/tong-quan-du-lich-quang-ngai'; 'bien-15'='https://vi.wikipedia.org/wiki/Ngư_cụ_đánh_bắt_cá'; 'bien-20'='https://fr.wikipedia.org/wiki/Bateau_panier'
}
foreach ($question in $questions) { if ($sources.ContainsKey($question.id)) { $question.nguon = $sources[$question.id] } }
